  ProductCollection* = ref object of RootObj
    ## The list of products, with details.
    products*: Option[ProductCollectionElementList]
    total_items*: Option[int64]
      ## The total number of items.
    total_pages*: Option[int64]
      ## The total number of pages.
    links*: Option[LinkDescriptionList]

  ProductCollectionElement* = ref object of RootObj
    ## The details for a product in the collection response.
    id*: Option[string]
      ## The ID of the product.
    name*: Option[string]
      ## The product name.
    description*: Option[string]
      ## The product description.
    create_time*: Option[DateTime]
    links*: Option[LinkDescriptionList]

  ProductCollectionElementList* = seq[ProductCollectionElement]

  ProductRequestPOST* = ref object of RootObj
    ## The create product request details.
    id*: Option[string]
      ## The ID of the product. You can specify the SKU for the product. If you omit the
      ## ID, the system generates it. System-generated IDs have the `PROD-` prefix.
    name*: string
      ## The product name.
    description*: Option[string]
      ## The product description.
    `type`*: string
      ## The product type. Indicates whether the product is physical or digital goods, or
      ## a service.
    category*: Option[ProductCategory]
    image_url*: Option[string]
      ## The image URL for the product.
    home_url*: Option[string]
      ## The home page URL for the product.

  ProductsCreate400* = ref object of RootObj
    details*: Option[seq[JsonNode]]

  ProductsPatch400* = ref object of RootObj
    details*: Option[seq[JsonNode]]

  ProductsPatch422* = ref object of RootObj
    details*: Option[seq[JsonNode]]
